Charts rendered clean — the metadata pass confirms **zero text/EXIF/time chunks** in either PNG, which is the requirement that most often fails silently. (The `findfont` warnings are matplotlib looking for a CJK serif it doesn't have; harmless, but I'll pin an available font in the real build.)

Now the assembled preview. Note every figure is a **placeholder**: values are invented, labels are `Region A–D`, and no customer-level data appears anywhere by construction.

```python
import base64, os, textwrap
from datetime import date

OUT = "/tmp/report_preview.html"
today = date(2026, 10, 12).isoformat()

KPI = [("Total value", "3,039", "+12.4%", "up"),
       ("Orders",      "1,284", "+8.1%",  "up"),
       ("Avg order",   "2.37",  "-3.9%",  "down"),
       ("Repeat rate", "18.6%", "+1.2pt", "up")]

kpi_html = "\n".join(
    f'<div class="kpi"><div class="label">{l}</div>'
    f'<div class="value">{v}</div>'
    f'<div class="delta {d}">{dl}</div></div>'
    for l, v, dl, d in KPI)

COMP_ROWS = "".join(
    f"<tr><td>{n}</td><td>{s}%</td></tr>"
    for n, s in [("Region A","31.4"),("Region B","26.8"),
                 ("Region C","18.2"),("Region D","13.9"),("Other","9.7")])

HTML = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="Purchase summary report.">
<title>Purchase Summary — 2026 H1</title>
<style>
*,*::before,*::after{{box-sizing:border-box}}
html,body,h1,h2,h3,p,ul,ol,figure,table{{margin:0;padding:0}}
ul,ol{{list-style:none}}
:root{{
  --ink:#1f2933; --ink-soft:#52606d; --rule:#d7dce1;
  --paper:#ffffff; --paper-alt:#f6f8fa;
  --c1:#0072b2; --c4:#d55e00; --c7:#f0e442;
  --font-sans:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,
              "Helvetica Neue",Arial,sans-serif;
  --font-num:ui-monospace,SFMono-Regular,"SF Mono",Menlo,Consolas,monospace;
  --fs-cover:2.25rem; --fs-h2:1.375rem; --fs-kpi:2rem;
  --fs-body:1rem; --fs-sm:.875rem; --fs-xs:.75rem;
  --s1:.5rem; --s2:1rem; --s3:1.5rem; --s4:2rem; --s5:3rem;
  --measure:68ch; --canvas:72rem;
}}
body{{font-family:var(--font-sans);font-size:var(--fs-body);line-height:1.6;
     color:var(--ink);background:var(--paper);-webkit-text-size-adjust:100%}}
.wrap{{max-width:var(--canvas);margin:0 auto;padding:0 var(--s3)}}
.prose{{max-width:var(--measure)}} .prose>*+*{{margin-top:var(--s2)}}
h1{{font-size:var(--fs-cover);line-height:1.15;letter-spacing:-.02em;font-weight:650}}
h2{{font-size:var(--fs-h2);line-height:1.3;font-weight:600;margin-top:var(--s5)}}
.subtitle{{color:var(--ink-soft);font-size:var(--fs-sm)}}
section{{padding-top:var(--s4)}}
section+section{{border-top:1px solid var(--rule);margin-top:var(--s4)}}
.kpis{{display:grid;gap:var(--s2);grid-template-columns:repeat(4,minmax(0,1fr));
       margin-top:var(--s3)}}
.kpi{{background:var(--paper-alt);border:1px solid var(--rule);border-radius:6px;
      padding:var(--s3)}}
.kpi .label{{font-size:var(--fs-xs);color:var(--ink-soft);text-transform:uppercase;
             letter-spacing:.07em}}
.kpi .value{{font-family:var(--font-num);font-size:var(--fs-kpi);line-height:1.1;
             font-variant-numeric:tabular-nums;margin-top:var(--s1);letter-spacing:-.02em}}
.kpi .delta{{font-size:var(--fs-sm);color:var(--ink-soft);margin-top:var(--s1)}}
.delta.up::before{{content:"\\25B2\\00a0";color:var(--c4)}}
.delta.down::before{{content:"\\25BC\\00a0";color:var(--c1)}}
figure{{margin-top:var(--s3)}}
figure img{{display:block;width:100%;height:auto;border:1px solid var(--rule);
            border-radius:6px}}
figcaption{{font-size:var(--fs-sm);color:var(--ink-soft);margin-top:var(--s2);
            max-width:var(--measure)}}
table{{width:100%;border-collapse:collapse;margin-top:var(--s3);font-size:var(--fs-sm);
       font-variant-numeric:tabular-nums}}
caption{{text-align:left;color:var(--ink-soft);font-size:var(--fs-sm);
         margin-bottom:var(--s2)}}
th,td{{text-align:right;padding:var(--s1) var(--s2);border-bottom:1px solid var(--rule)}}
th:first-child,td:first-child{{text-align:left}}
thead th{{border-bottom:2px solid var(--ink);color:var(--ink-soft);font-weight:600}}
tbody tr:nth-child(even){{background:var(--paper-alt)}}
.note{{background:var(--paper-alt);border-left:3px solid var(--c1);
       border-radius:0 6px 6px 0;padding:var(--s3);font-size:var(--fs-sm);
       color:var(--ink-soft);max-width:var(--measure)}}
@media (max-width:60rem){{.kpis{{grid-template-columns:repeat(2,1fr)}}}}
@media (max-width:34rem){{
  :root{{--fs-cover:1.75rem;--fs-kpi:1.6rem}}
  .wrap{{padding:0 var(--s2)}} .kpis{{grid-template-columns:1fr}}
  table{{font-size:var(--fs-xs)}} th,td{{padding:var(--s1)}}}}
@media print{{
  *{{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
  :root{{--fs-cover:1.75rem;--canvas:100%}}
  body{{font-size:10.5pt;line-height:1.45}}
  h2,figure,table,.kpis{{break-inside:avoid}}}}
</style>
</head>
<body>
<div class="wrap">

  <header class="prose" style="padding-top:var(--s5)">
    <h1>Purchase Summary</h1>
    <p class="subtitle">2026 H1 · placeholder preview · {today}</p>
  </header>

  <section>
    <h2>Headline</h2>
    <div class="kpis">{kpi_html}</div>
  </section>

  <section>
    <h2>Trend</h2>
    <figure>
      <img alt="Placeholder chart: monthly totals, Jan to Jun."
           src="data:image/png;base64,{ch_trend}">
      <figcaption>Placeholder. Monthly totals show a moderate rise Jan–May,
      easing in June. Values are synthetic.</figcaption>
    </figure>
  </section>

  <section>
    <h2>Composition</h2>
    <figure>
      <img alt="Placeholder chart: share of total by region."
           src="data:image/png;base64,{ch_comp}">
      <figcaption>Placeholder. Region A accounts for the largest share;
      the five smallest categories are merged into “Other”.</figcaption>
    </figure>
    <table>
      <caption>Share of total by region (placeholder)</caption>
      <thead><tr><th>Region</th><th>Share</th></tr></thead>
      <tbody>{COMP_ROWS}</tbody>
    </table>
  </section>

  <section>
    <h2>Method &amp; privacy</h2>
    <p class="note">This preview uses invented values. The final report is
    aggregate-only: no names, contact details, identifiers, or free-text fields
    appear in the document, its chart images, or its metadata. Groups below the
    suppression threshold are merged or omitted. Figures are rounded.</p>
  </section>

</div>
</body>
</html>"""

with open(OUT, "w", encoding="utf-8") as fh:
    fh.write(HTML)

raw = open(OUT, "rb").read()
print("written      :", OUT)
print("size         :", f"{len(raw)/1024:.0f} KB")
print("self-contained:", b'src="data:image/png;base64' in raw)
print("external refs :", raw.count(b"http://") + raw.count(b"https://"),
      "| <script> tags:", raw.count(b"<script"))
print("date now      :", today)
